function directConfig(extra = {}) { const config = createDefaultProxyConfiguration(); config.profiles = [{ id: 'direct', name: 'Local fixture', type: 'socks5', host: '127.0.0.1', port: 1080, native: false }]; config.selectedId = 'direct'; return { ...config, ...extra }; }
