test('strict metadata canonicalization is deterministic and preserves empty inactive routing', () => { const config = directConfig(); assert.deepEqual(parseProxyConfiguration(exportProxyConfiguration(config)), config); assert.equal(config.killSwitch, true); assert.equal(config.enabled, false); assert.equal(config.autoConnect, false); });
test('config rejects secrets, duplicate profiles, unknown fields and disabled kill switch', () => { for (const mutate of [c => c.profiles[0].password = 'secret', c => c.profiles.push({ ...c.profiles[0] }), c => c.extra = 1, c => c.killSwitch = false, c => c.routing.proxyDomains = ['*.com', '*.com']]) { const config = directConfig(); mutate(config); assert.throws(() => validateProxyConfiguration(config)); } });
test('config rejects accessors without invoking them', () => { let count = 0; const c = directConfig(); Object.defineProperty(c, 'enabled', { enumerable: true, get() { count++; return true; } }); assert.throws(() => validateProxyConfiguration(c)); assert.equal(count, 0); });
test('host parser accepts canonical IP families and rejects URL syntax, local DNS shorthands and numeric ambiguities', () => { assert.equal(proxyHost('[2001:0db8::1]'), '2001:db8::1'); assert.equal(proxyHost('EXAMPLE.COM.'), 'example.com'); for (const host of ['127.1', '0177.0.0.1', '1.2.3.256', 'foo/bar', 'user@foo', 'foo%00', 'x;DIRECT', 'a b', 'fe80::1%eth0']) assert.throws(() => proxyHost(host)); });
test('SOCKS input handles IPv6, percent encoded secrets and legacy host port credentials', () => { assert.deepEqual(parseProxyProfileText('socks5h://user:p%40ss@[2001:db8::1]:1080'), { type: 'socks5', host: '2001:db8::1', port: 1080, username: 'user', password: 'p@ss' }); assert.equal(parseProxyProfileText('proxy.example:1080:user:pass').password, 'pass'); assert.equal(parseProxyProfileText('user:pass@proxy.example:1080').username, 'user'); assert.throws(() => parseProxyProfileText('socks4://proxy.example:1080')); assert.equal(parseProxyProfileText('https://proxy.example:1080').type, 'https'); });
test('VLESS Markdown escapes normalize and duplicate/unknown/insecure query parameters reject', () => { const base = 'vless://01234567-89ab-cdef-0123-456789abcdef@relay.example:443'; assert.equal(parseProxyProfileText(base.replace('vless:', 'vless\\:') + '?security=reality&pbk=a\\_b').uri, base + '?security=reality&pbk=a_b'); for (const suffix of ['?security=tls&security=none', '?evil=1', '?allowInsecure=true']) assert.throws(() => normalizeVlessUri(base + suffix)); });
test('profile validation does not accept unsolicited per-type secret fields', () => { assert.throws(() => validateProxyProfileInput({ name: 'x', type: 'socks5', host: 'example.com', port: 1080, config: 'bad' })); assert.throws(() => validateProxyProfileInput({ name: 'x', type: 'vless', uri: 'vless://bad', password: 'x' })); });
test('generated PAC routes literal targets without DNS queries or DIRECT fallback', () => { const c = directConfig(); c.routing.bypassLocal = false; const pac = buildProxyPac(c, { host: '2001:db8::1', port: 1080 }); assert.match(pac, /SOCKS5 \[2001:db8::1\]:1080/); assert.doesNotMatch(pac, /dnsResolve|isResolvable|; DIRECT/); assert.equal(pacResult(c, 'remote.example'), 'SOCKS5 127.0.0.1:1080'); });
test('PAC exact/wildcard routes and local bypass are bounded and predictable', () => { const c = directConfig(); c.routing.mode = 'include'; c.routing.proxyDomains = ['exact.example', '*.sub.example']; assert.equal(pacResult(c, 'exact.example'), 'SOCKS5 127.0.0.1:1080'); assert.equal(pacResult(c, 'a.exact.example'), 'DIRECT'); assert.equal(pacResult(c, 'a.sub.example'), 'SOCKS5 127.0.0.1:1080'); assert.equal(pacResult(c, 'sub.example'), 'DIRECT'); c.routing.mode = 'all'; for (const host of ['localhost', 'x.local', '10.1.2.3', '172.31.1.1', '[fd01::1]']) assert.equal(pacResult(c, host), 'DIRECT'); assert.equal(pacResult(c, '172.32.1.1'), 'SOCKS5 127.0.0.1:1080'); });
test('privileged sender accepts only exact owned top-level Options', () => { const api = { runtime: { id: 'owned', getURL: path => 'chrome-extension://owned/' + path } }; const base = { id: 'owned', origin: 'chrome-extension://owned', url: api.runtime.getURL('options.html') }; assert.equal(isProxyUiSender(api, base), true); for (const patch of [{ id: 'other' }, { tab: { id: 2 } }, { frameId: 1 }, { url: 'https://evil/options.html' }, { url: api.runtime.getURL('popup.html') }, { origin: 'https://evil' }]) assert.equal(isProxyUiSender(api, { ...base, ...patch }), false); });
test('native unauthenticated SOCKS profile saves metadata without contacting native host', async () => { const f = fixture(); try { const result = await f.client.saveProfile({ name: 'Test', type: 'socks5', host: 'proxy.example', port: 1080 }); assert.equal(result.configuration.profiles[0].native, false); assert.equal(f.nativeMessages.length, 0); assert.equal(f.operations.length, 0); } finally { f.cleanup(); } });
test('authenticated SOCKS profile secrets travel only to native vault and never metadata storage or snapshots', async () => { const f = fixture(); try { const result = await f.client.saveProfile({ name: 'Auth', type: 'socks5', host: 'proxy.example', port: 1080, username: 'USER-CANARY', password: 'PASS-CANARY' }); assert.equal(result.configuration.profiles[0].native, true); assert.equal(f.nativeMessages.find(item => item.op === 'save').profile.password, 'PASS-CANARY'); for (const value of [f.data, f.changes, result]) assert.doesNotMatch(JSON.stringify(value), /USER-CANARY|PASS-CANARY/); } finally { f.cleanup(); } });
test('native vault record rename preserves secret and calls no native save', async () => { const f = fixture(); try { const saved = await f.client.saveProfile({ name: 'Auth', type: 'socks5', host: 'proxy.example', port: 1080, username: 'u', password: 'p' }); const profile = saved.configuration.profiles[0], before = f.nativeMessages.length; const result = await f.client.saveProfile({ id: profile.id, name: 'Renamed', type: 'socks5', host: profile.host, port: profile.port }); assert.equal(result.configuration.profiles[0].name, 'Renamed'); assert.equal(f.nativeMessages.length, before); } finally { f.cleanup(); } });
test('connect applies generated mandatory Chrome PAC, readback and privacy overlay; disconnect only releases owned layer', async () => { const f = fixture({ initial: directConfig() }); try { const result = await f.client.connect('direct'); assert.equal(result.status.state, 'connected'); assert.equal(f.setting.pacScript.mandatory, true); assert.match(f.setting.pacScript.data, /SOCKS5 127\.0\.0\.1:1080/); assert.equal(f.overlays.at(-1).active, true); const off = await f.client.disconnect(); assert.equal(off.status.state, 'off'); assert.equal(off.configuration.enabled, false); assert.equal(f.operations.at(-1)[0], 'clear'); assert.equal(f.overlays.at(-1).active, false); } finally { f.cleanup(); } });
test('another controlling extension is not overwritten and profile remains disabled', async () => { const f = fixture({ initial: directConfig(), control: 'controlled_by_other_extensions' }); try { await assert.rejects(f.client.connect('direct'), fail('not-controllable')); assert.equal(f.operations.length, 0); assert.equal(f.service.snapshot().configuration.enabled, false); } finally { f.cleanup(); } });
test('disconnect clears our hidden layer without modifying the other extension value', async () => { const f = fixture({ initial: directConfig() }); try { await f.client.connect('direct'); f.level = 'controlled_by_other_extensions'; await f.client.disconnect(); assert.equal(f.operations.at(-1)[0], 'clear'); } finally { f.cleanup(); } });
test('privacy permission refusal never opens native host or mutates proxy setting', async () => { const f = fixture({ initial: directConfig(), privacy: false }); try { await assert.rejects(f.client.connect('direct'), fail('permission-required')); assert.equal(f.operations.length, 0); assert.equal(f.nativeMessages.length, 0); } finally { f.cleanup(); } });
test('native relay connects through closed sentinel and stops on explicit disconnect', async () => { const f = fixture(); try { const saved = await f.client.saveProfile({ name: 'Auth', type: 'socks5', host: 'proxy.example', port: 1080, username: 'u', password: 'p' }); const result = await f.client.connect(saved.configuration.selectedId); assert.equal(result.status.endpoint.port, 32123); assert.match(f.operations[0][1].value.pacScript.data, /127\.0\.0\.1:9/); assert.equal(f.nativeMessages.at(-1).op, 'connect'); await f.client.disconnect(); assert.equal(f.nativeMessages.at(-1).op, 'disconnect'); } finally { f.cleanup(); } });
test('native host crash keeps mandatory PAC and desired enabled profile, never DIRECT', async () => { const f = fixture(); try { const saved = await f.client.saveProfile({ name: 'Auth', type: 'socks5', host: 'proxy.example', port: 1080, username: 'u', password: 'p' }); await f.client.connect(saved.configuration.selectedId); const before = f.setting; f.nativePorts[0].disconnect(); await tick(); const result = await f.client.load(); assert.equal(result.status.state, 'blocked'); assert.equal(result.configuration.enabled, true); assert.deepEqual(f.setting, before); assert.equal(f.operations.some(op => op[0] === 'clear'), false); } finally { f.cleanup(); } });
test('native connection refusal retains closed route and strips raw error text', async () => { const f = fixture({ nativeHandler(message, respond, server) { if (message.op === 'hello') return respond({ version: 1, capabilities: { socks5: true, openvpn: true, vless: true, vault: true } }); if (message.op === 'save') return respond({ profileId: message.profileId, summary: { type: 'socks5', host: 'proxy.example', port: 1080 } }); server.postMessage({ v: 1, id: message.id, ok: false, error: { code: 'connection-refused', message: 'SECRET-CANARY' } }); } }); try { const saved = await f.client.saveProfile({ name: 'Auth', type: 'socks5', host: 'proxy.example', port: 1080, username: 'u', password: 'p' }); await assert.rejects(f.client.connect(saved.configuration.selectedId), fail('connection-refused')); assert.equal(f.service.snapshot().status.state, 'blocked'); assert.match(f.setting.pacScript.data, /127\.0\.0\.1:9/); assert.doesNotMatch(JSON.stringify(f.changes), /SECRET-CANARY/); } finally { f.cleanup(); } });
