test('Firefox listener registers synchronously, waits startup and returns terminal null without settings.set', async () => { const f = fixture({ firefox: true, initial: directConfig({ enabled: true }) }); try { assert.equal(f.api.proxy.onRequest.size, 1); const [response] = f.api.proxy.onRequest.emit({ url: 'https://remote.example/' }); assert.deepEqual(await response, [{ type: 'socks', host: '127.0.0.1', port: 1080, proxyDNS: true, failoverTimeout: 1 }, null]); assert.equal(f.operations.length, 0); } finally { f.cleanup(); } });
