test('settings CAS rejects stale revision and registry substitution before any write', async () => { const f = fixture({ initial: directConfig() }); try { const current = await f.client.load(); const changed = { ...current.configuration, autoConnect: true }; const next = await f.client.saveSettings(changed); const before = f.writes.length; await assert.rejects(f.client.saveSettings(changed), fail('stale-revision')); assert.equal(f.writes.length, before); const bad = structuredClone(next.configuration); bad.profiles[0].host = 'other.example'; await assert.rejects(f.client.saveSettings(bad), fail('invalid-config')); assert.equal(f.writes.length, before); } finally { f.cleanup(); } });
test('client timeout retains outstanding physical mutation and blocks duplicate dispatch', async () => { let release; const wait = new Promise(resolve => { release = resolve; }); const f = fixture({ initial: directConfig(), storageSet: () => wait }); const client = createProxyClient(f.api, { env: f.env, deadline: 10 }); try { await assert.rejects(client.connect('direct'), fail('timeout')); await assert.rejects(client.connect('direct'), fail('busy')); assert.equal(f.operations.length, 0); release(); await tick(); await tick(); assert.equal((await client.load()).status.state, 'connected'); assert.equal(f.writes.length, 1); } finally { release(); client.dispose(); f.cleanup(); } });
test('service global physical mutation lock excludes second Options client', async () => { let release; const wait = new Promise(resolve => { release = resolve; }); const f = fixture({ initial: directConfig(), storageSet: () => wait }); const other = createProxyClient(f.api, { env: f.env }); try { const first = f.client.connect('direct'); await tick(); await assert.rejects(other.connect('direct'), fail('busy')); release(); await first; assert.equal(f.writes.length, 1); } finally { release(); other.dispose(); f.cleanup(); } });
