test('corrupt persisted metadata is quarantined without writes or DIRECT fallback in either browser', async () => { for (const firefox of [false, true]) { const invalid = { format: 'unknown', enabled: true, password: 'NEVER-EXPOSE' }, f = fixture({ firefox, initial: invalid }); try { await f.service.ready; assert.equal(f.service.snapshot().status.state, 'error'); assert.equal(f.writes.length, 0); assert.deepEqual(f.data[PROXY_STORAGE_KEY], invalid); assert.doesNotMatch(JSON.stringify(f.service.snapshot()), /NEVER-EXPOSE/); if (firefox) assert.equal((await f.api.proxy.onRequest.emit({ url: 'https://localhost/' })[0])[0].port, 9); else assert.match(f.setting.pacScript.data, /127\.0\.0\.1:9/); await f.client.disconnect(); assert.deepEqual(f.data[PROXY_STORAGE_KEY], invalid); assert.equal(f.service.snapshot().status.state, 'off'); } finally { f.cleanup(); } } });
test('native status refresh preserves safe engine diagnostics and never arbitrary native text', async () => { const f = fixture({ nativeHandler(message, respond) { if (message.op === 'hello') return respond({ version: 1, capabilities: { socks5: true, openvpn: true, vless: true, vault: true } }); if (message.op === 'save') return respond({ profileId: message.profileId, summary: { type: 'socks5', host: 'proxy.example', port: 1080 } }); if (message.op === 'connect') return respond({ profileId: message.profileId, host: '127.0.0.1', port: 32123 }); if (message.op === 'status') return respond({ state: 'blocked', diagnostic: { code: 'engine-failed', phase: 'engine', retryable: true, message: 'SECRET-CHILD-OUTPUT' } }); respond({}); } }); try { const saved = await f.client.saveProfile({ name: 'Auth', type: 'socks5', host: 'proxy.example', port: 1080, username: 'u', password: 'p' }); await f.client.connect(saved.configuration.selectedId); const refreshed = await f.client.load(); assert.deepEqual(refreshed.status, { state: 'blocked', code: 'engine-failed', phase: 'engine', retryable: true, profileId: saved.configuration.selectedId }); assert.doesNotMatch(JSON.stringify(f.changes), /SECRET-CHILD-OUTPUT/); } finally { f.cleanup(); } });
test('native errors retain enum phase/retry advice through client rejection and status', async () => { const f = fixture({ nativeHandler(message, respond, server) { if (message.op === 'hello') return respond({ version: 1, capabilities: { socks5: true, openvpn: true, vless: true, vault: true } }); if (message.op === 'save') return respond({ profileId: message.profileId, summary: { type: 'socks5', host: 'proxy.example', port: 1080 } }); server.postMessage({ v: 1, id: message.id, ok: false, error: { code: 'auth-failed', phase: 'auth', retryable: false, message: 'PASSWORD-CANARY' } }); } }); try { const saved = await f.client.saveProfile({ name: 'Auth', type: 'socks5', host: 'proxy.example', port: 1080, username: 'u', password: 'p' }); await assert.rejects(f.client.connect(saved.configuration.selectedId), error => error.code === 'auth-failed' && error.phase === 'auth' && error.retryable === false); assert.equal(f.service.snapshot().status.phase, 'auth'); assert.doesNotMatch(JSON.stringify(f.changes), /PASSWORD-CANARY/); } finally { f.cleanup(); } });
