function managerHandler(records, override = null) {
  let active = null;
  return (message, respond, server) => {
    if (override?.(message, respond, server)) return;
    if (message.op === 'save') {
      records.set(message.profileId, structuredClone(message.profile));
      const uri = message.profile.uri ? new URL(message.profile.uri) : null;
      return respond({ profileId: message.profileId, summary: { type: message.profile.type, host: message.profile.host ?? uri?.hostname ?? null, port: message.profile.port ?? (uri ? Number(uri.port) : null) } });
    }
    if (message.op === 'connect') { active = message.profileId; return respond({ profileId: active, host: '127.0.0.1', port: 32123 }); }
    if (message.op === 'delete') { records.delete(message.profileId); return respond({ deleted: true }); }
    if (message.op === 'disconnect') { active = null; return respond({}); }
    if (message.op === 'status') return respond({ state: active ? 'connected' : 'off', profileId: active, diagnostic: null });
    if (message.op === 'check') return respond(diagnosticPass());
    if (message.op === 'export') return respond({ profiles: message.profileIds.map(profileId => ({ profileId, profile: structuredClone(records.get(profileId)) })) });
    diagnosticHandler(message, respond, server);
  };
}
