test('a full portable export above 32 MiB rejects atomically even when each individual OpenVPN record is within its own bound', () => {
  const config = createDefaultProxyConfiguration(), connection = { type: 'openvpn', config: 'client\n' + '\n'.repeat(200000), username: '', password: '' };
  const input = { ...config, format: 'detect.expert.proxy.bundle', profiles: Array.from({ length: 90 }, (_, index) => ({ id: 'p' + index, name: 'VPN ' + index, type: 'openvpn', host: null, port: null, native: true, connection })) };
  assert.throws(() => validateProxyBundle(input), fail('capacity'));
});
test('renaming an active direct or native profile changes only its name and revision without reconnecting or replacing any connection', async () => {
  for (const nativeProfile of [false, true]) {
    const f = fixture({ initial: directConfig() });
    try {
      const saved = nativeProfile ? await f.client.saveProfile({ name: 'Auth', type: 'socks5', host: 'proxy.example', port: 1080, username: 'u', password: 'p' }) : await f.client.load();
      const id = nativeProfile ? saved.configuration.profiles.find(profile => profile.native).id : 'direct';
      await f.client.connect(id); const before = f.service.snapshot(), metadata = before.configuration.profiles.find(profile => profile.id === id), messages = f.nativeMessages.length, operations = f.operations.length;
      const renamed = await f.client.saveProfile({ id, name: 'Renamed active', type: metadata.type, host: metadata.host, port: metadata.port });
      assert.equal(renamed.configuration.profiles.find(profile => profile.id === id).name, 'Renamed active'); assert.equal(renamed.configuration.revision, before.configuration.revision + 1); assert.deepEqual(renamed.status, before.status); assert.equal(renamed.configuration.enabled, true); assert.equal(renamed.configuration.selectedId, id);
      assert.equal(f.nativeMessages.length, messages); assert.equal(f.operations.length, operations);
      await assert.rejects(f.client.saveProfile({ id, name: 'Changed connection', type: 'socks5', host: 'changed.example', port: 1080, username: nativeProfile ? 'u' : '', password: nativeProfile ? 'p' : '' }), fail('busy'));
    } finally { f.cleanup(); }
  }
});
test('vault Save, full export, Companion check and Delete need native access but never the unrelated default browser privacy grant', async () => {
  const records = new Map(), f = fixture({ privacy: false, nativeHandler: managerHandler(records) });
  try {
    const saved = await f.client.saveProfile({ name: 'Default native', type: 'socks5', host: 'proxy.example', port: 1080, username: 'u', password: 'p' });
    const id = saved.configuration.selectedId; assert.equal(saved.configuration.protectWebRTC, true); assert.equal(saved.configuration.disablePrediction, true);
    assert.equal((await f.client.hostStatus()).host.available, true); assert.equal((await f.client.exportProfiles(id)).profiles[0].connection.password, 'p');
    await assert.rejects(f.client.connect(id), fail('permission-required')); assert.equal(f.service.snapshot().configuration.enabled, false); assert.equal(f.operations.length, 0);
    assert.equal((await f.client.deleteProfile(id)).configuration.profiles.length, 0);
  } finally { f.cleanup(); }
});
